    ('43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, 'Quiz — Haber, l’auxiliaire unique', 'Espagnol', '3e', 'L’auxiliaire haber', 'dd26076d-17ae-5e12-9efd-42fc0aec6fd6'::uuid),
    ('6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, 'Quiz — Se, et ses cinq valeurs', 'Espagnol', '3e', 'Les verbes pronominaux', '269045f3-a8d2-5a5e-9d3b-7f952ef93466'::uuid),
    ('654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, 'Quiz — E → ie, o → ue : l’accent tonique commande', 'Espagnol', '3e', 'Les verbes à diphtongue', '78f58be8-d95a-531c-b5d8-8c6660759477'::uuid),
    ('26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, 'Quiz — E → i : la famille de pedir', 'Espagnol', '3e', 'Les verbes à affaiblissement', 'eb7ad41f-f1ed-5cc6-978d-3cc262bad72d'::uuid),
    ('7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, 'Quiz — Deux verbes « être », et tout se joue là', 'Espagnol', '3e', 'Ser et estar', '0868cada-de98-5150-a43d-4331d996ffe8'::uuid),
    ('b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, 'Quiz — Estar + gérondif, et les tournures de durée', 'Espagnol', '3e', 'Le gérondif', '1c06854a-0cbe-5ad5-b2b2-466cc3eddade'::uuid),
    ('622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'Quiz — Accord ou pas : la question qui tranche', 'Espagnol', '3e', 'Le participe passé', '97f86426-6c7d-5f51-8a45-0670abaef3a4'::uuid),
    ('2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, 'Quiz — La construction inversée', 'Espagnol', '3e', 'Les verbes du type « gustar »', '8470d8ec-2f2c-56a0-8c77-3ee5ced6229f'::uuid),
    ('0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, 'Quiz — Tener que, hay que, deber', 'Espagnol', '3e', 'L’obligation', '204eaa61-bd16-5e0b-8491-89a98e0d5543'::uuid),
    ('9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, 'Quiz — Soler, et les tournures de répétition', 'Espagnol', '3e', 'L’habitude', '20441766-6210-5016-b49a-0c86417e85a0'::uuid),
    ('2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, 'Quiz — Le futur et le conditionnel de supposition', 'Espagnol', '3e', 'La probabilité', '2248e756-60aa-5c77-9eca-20655cab10a7'::uuid),
    ('fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'Quiz — Conseiller, suggérer, ordonner', 'Espagnol', '3e', 'Le conseil', '16cf06b0-8bc9-58f6-882b-7e285dffa72a'::uuid),
    ('fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, 'Quiz — Trois conjugaisons et les irréguliers qui comptent', 'Espagnol', '3e', 'Le présent de l’indicatif', '38434152-ad07-5921-8557-2496f1cecafb'::uuid),
    ('1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'Quiz — La voyelle qui bascule', 'Espagnol', '3e', 'Le subjonctif présent', '4bd56a7c-2061-5a0e-9d0a-d4ba99005604'::uuid),
    ('6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, 'Quiz — Le temps du décor et de l’habitude', 'Espagnol', '3e', 'L’imparfait', '786d9d25-a57f-505f-a73a-8ca254bec9ff'::uuid),
    ('0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, 'Quiz — El pretérito perfecto : le passé qui touche au présent', 'Espagnol', '3e', 'Le passé composé', '9cd6e638-16b4-5612-afde-d36223a35d6c'::uuid),
    ('6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, 'Quiz — El pretérito indefinido : le temps du récit', 'Espagnol', '3e', 'Le passé simple', '07656018-c9a4-55ac-95af-8237ee25df98'::uuid),
    ('a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, 'Quiz — Futur simple, futur proche, et le conditionnel qui en dérive', 'Espagnol', '3e', 'Le futur', '76479552-d2cd-546f-ba2d-27447dfdcce3'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('182989af-732f-5430-b2cd-fb74b25391ff'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, 'Comment s’écrit une question en espagnol ?', 'mcq', '["Avec un ¿ à l’ouverture et un ? à la fermeture","Avec un seul ? final","Avec un ¿ seulement","Avec « est-ce que » puis un ?"]'::jsonb, 0, 'Le ¿ se place au début de la partie interrogée, pas forcément de la phrase.', 1),
    ('6028f4d7-c61c-506b-a36e-6a907c7f24ed'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, 'Les mots interrogatifs espagnols portent tous un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est lui qui distingue *dónde* (interrogatif) de *donde* (relatif).', 2),
    ('caeb4596-460e-56b6-af96-72566fd1ca72'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, 'Que demande « cuál » plutôt que « qué » ?', 'mcq', '["Un choix dans un ensemble","Une définition","Une cause","Une quantité"]'::jsonb, 0, '*¿Cuál prefieres?* suppose plusieurs possibilités déjà connues.', 3),
    ('c8dee7dc-7451-5eaa-935a-38988aeb475e'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, 'Comment traduire « Pourquoi pleures-tu ? » ?', 'mcq', '["¿Por qué lloras?","¿Porque lloras?","¿Porqué lloras?","¿Por que lloras?"]'::jsonb, 0, 'En deux mots et avec l’accent : c’est la question, pas la réponse.', 4),
    ('62e5fa54-055c-5a8a-816e-8069932d526b'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, '« El porqué » est un nom masculin qui signifie « la raison ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*No entiendo el porqué de su decisión.*', 5),
    ('13fe12bd-4c06-574d-baaa-43d4bd11d20f'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, 'Dans « No sé dónde está », l’accent sur « dónde »…', 'mcq', '["Se maintient malgré l’absence de point d’interrogation","Disparaît","Devient facultatif","Se déplace"]'::jsonb, 0, 'C’est une interrogation indirecte : l’accent reste, les signes ¿ ? partent.', 6),
    ('c6b12cb1-7e41-589d-a71c-298c6be95f20'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, 'L’espagnol exige l’inversion du sujet dans toute question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*¿Tú hablas español?* est parfaitement correct : l’intonation suffit.', 7),
    ('5fa2e56c-5f1f-5dd2-aa20-522860e06ba6'::uuid, 'aababadf-afe9-52cc-a035-2c37d64e270d'::uuid, 'Devant un nom, l’espagnol préfère…', 'mcq', '["Qué (¿Qué día es hoy?)","Cuál (¿Cuál día es hoy?)","Quién","Cuánto"]'::jsonb, 0, '*¿Cuál día?* est un calque du français à éviter.', 8),
    ('0c91cdf2-61cb-5e79-92e2-8b6b96ba3136'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, 'Où se place « no » dans la phrase ?', 'mcq', '["Juste devant le verbe","À la fin de la phrase","Après le verbe","Devant le sujet"]'::jsonb, 0, 'Seuls les pronoms compléments peuvent s’intercaler : *No te lo digo.*', 1),
    ('0dbb7002-8092-51bd-bf89-15b0dd9bfbbf'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, 'Comment traduire « je ne vois rien » ?', 'mcq', '["No veo nada","Veo nada","No veo","Nada veo no"]'::jsonb, 0, 'La double négation est obligatoire quand le mot négatif suit le verbe.', 2),
    ('3b8f85f9-4c65-5df4-a632-a2aeb3f5c73b'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, '« Nadie viene » est incorrect : il manque le « no ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand le mot négatif précède le verbe, le *no* disparaît.', 3),
    ('0ac53425-e675-5ac5-8b02-6184deb693ff'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, 'Que signifie « tampoco » ?', 'mcq', '["Non plus","Encore","Déjà","Jamais"]'::jsonb, 0, '*A mí tampoco me gusta* : à moi non plus.', 4),
    ('36123e64-2dab-57c6-9f66-5c7a14d7917c'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, 'Comment dit-on « ne… plus » ?', 'mcq', '["Ya no","Todavía no","Nunca","Ni"]'::jsonb, 0, '*Ya no fumo* : je ne fume plus. *Todavía no* signifie « pas encore ».', 5),
    ('c1445f26-632b-5ada-ada3-7813e344b658'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["Sino","Pero","Porque","Aunque"]'::jsonb, 0, '*No es francés sino español.* *Pero* oppose sans rectifier.', 6),
    ('1c4a6fc3-99e0-5cb7-bf65-91fa289373b3'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, '« Ninguno » s’apocope en « ningún » devant un masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ningún libro*, mais *ninguna casa* et *ninguno de ellos*.', 7),
    ('a53a9f25-d494-5442-8bc1-37574bb038fb'::uuid, '0df47a82-8721-53da-839a-662a2d25d14c'::uuid, 'Devant un verbe conjugué, « sino » devient…', 'mcq', '["Sino que","Sino de","Sino a","Sino el"]'::jsonb, 0, '*No canta sino que grita.*', 8),
    ('1094aeda-3682-5d0c-90d5-52124c6ef51b'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, 'Quelle relative s’écrit entre virgules ?', 'mcq', '["L’explicative","La déterminative","Les deux","Aucune"]'::jsonb, 0, 'L’explicative ajoute une information supprimable.', 1),
    ('8e040eb1-925b-5896-a742-310945874b1a'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, '« Busco una secretaria que hable inglés » emploie le subjonctif parce que…', 'mcq', '["L’antécédent est indéfini : elle reste à trouver","L’antécédent est connu","La relative est explicative","Le verbe est irrégulier"]'::jsonb, 0, 'Avec un antécédent réel, l’indicatif : *que habla inglés*.', 2),
    ('c6278823-df09-5d01-9ef9-dfb51859450a'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, 'La virgule d’une relative ne change pas le sens de la phrase.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Los alumnos que estudian* ne désigne pas les mêmes élèves que *los alumnos, que estudian*.', 3),
    ('df65dd7a-553a-54ba-8ee6-1c37883e3d03'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo en","La casa vivo en que","La casa en vivo que"]'::jsonb, 0, 'La préposition précède toujours le relatif en espagnol.', 4),
    ('5ac43de6-e475-5b20-9e64-6866e6cd1ca1'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, 'Après « No conozco a nadie que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au gérondif"]'::jsonb, 0, 'La négation rend l’antécédent inexistant, donc indéfini.', 5),
    ('1b5c06b7-2c2e-5e3c-ad87-166b1f6bb90f'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, 'Pour renvoyer à une idée entière, on emploie…', 'mcq', '["Lo que","El que","Quien","Cuyo"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 6),
    ('9dd50ed9-ff29-5841-a74c-76fa33fd13b8'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, 'Dans une relative déterminative, on emploie normalement « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Quien* est réservé aux explicatives et aux emplois avec préposition.', 7),
    ('c5f89e02-fb27-5021-89c4-b755cab511ee'::uuid, 'ec8141a3-5d96-54d6-9958-4548226f1d05'::uuid, '« El que quiera, que venga » se traduit par…', 'mcq', '["Que celui qui veut vienne","Ce qu’il veut, qu’il vienne","Celui qu’il veut vient","Il veut qu’il vienne"]'::jsonb, 0, 'Relatif sans antécédent exprimé, suivi du subjonctif.', 8),
    ('a3459b53-51c5-5ffb-a26f-28995c972f7b'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, 'Après « Quiero que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au conditionnel"]'::jsonb, 0, 'La volonté commande le subjonctif : *Quiero que vengas.*', 1),
    ('d62b4a73-da4f-59b8-8eff-7376fa462cc9'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, '« Creo que viene » et « No creo que venga » emploient le même mode.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nier la certitude fait passer l’indicatif au subjonctif.', 2),
    ('095333a7-d9e6-5b96-b40b-801f738998eb'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, 'Comment dit-on « je veux venir » (même sujet) ?', 'mcq', '["Quiero venir","Quiero que venga","Quiero que vengo","Quiero de venir"]'::jsonb, 0, 'Même sujet : infinitif, sans *que*.', 3),
    ('f0a79d45-dc10-5286-92b3-212571c60ef3'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, 'Après « Es necesario que… », on emploie…', 'mcq', '["Le subjonctif","L’indicatif","Le gérondif","Le participe"]'::jsonb, 0, 'Le jugement impersonnel commande le subjonctif : *que estudies*.', 4),
    ('5bbd2a51-0512-5a09-82e4-f76bcff45314'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, '« Ojalá » est toujours suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ojalá llueva* : c’est l’expression du souhait par excellence.', 5),
    ('265a9985-f402-53c5-aa3a-453f33bd5cb7'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, 'Quand le verbe principal est au passé, le subjonctif présent devient…', 'mcq', '["L’imparfait du subjonctif","Le passé simple","Le conditionnel","Le futur"]'::jsonb, 0, '*Quería que vinieras* — les formes en -ra et en -se sont équivalentes.', 6),
    ('baf89f49-4133-5d59-9c73-349e63ff4dff'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, 'Après « Dudo que… », on emploie l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le doute appelle le subjonctif : *Dudo que sea verdad.*', 7),
    ('2f4434dc-5c90-578c-84d2-7a8e7bc47f0d'::uuid, '29527a2c-897e-5822-8c40-3321854032d3'::uuid, 'Le « que » de la complétive peut être supprimé en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se maintient toujours : *Espero que me llames.*', 8),
    ('9938a00d-2f0e-5501-8f98-48744e2b0bc8'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, 'Quel est le genre de « la sangre » ?', 'mcq', '["Féminin","Masculin","Neutre","Les deux"]'::jsonb, 0, 'Piège classique : le français dit « le sang ».', 1),
    ('6a1afadf-917e-5be9-ba61-a80a14849349'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, 'Les noms en « -ción » et « -dad » sont féminins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La canción*, *la ciudad*, *la libertad*.', 2),
    ('5274a967-1919-5c65-99a3-90f46c53a55d'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, 'Quel est le genre de « el problema » ?', 'mcq', '["Masculin, malgré le -a final","Féminin","Variable","Neutre"]'::jsonb, 0, 'Comme *el tema*, *el idioma*, *el sistema* : origine grecque.', 3),
    ('31bd2464-f1d6-504d-8fd4-f510833b83a3'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, 'Quel est le pluriel de « lápiz » ?', 'mcq', '["Lápices","Lápizs","Lápizes","Lápiz"]'::jsonb, 0, 'Le -z devient -c devant -es.', 4),
    ('2f372db0-65a7-53cf-9592-29b6b5bd4c7a'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, '« El lunes » au pluriel devient « los lunes ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les mots en -s non accentués sur la dernière syllabe sont invariables.', 5),
    ('d5513026-bbd1-5236-9e8d-ab0c8c225cdb'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, 'Quel est le pluriel de « el examen » ?', 'mcq', '["Los exámenes","Los examenes","Los exámens","Los examen"]'::jsonb, 0, 'L’accent écrit apparaît pour conserver la même syllabe tonique.', 6),
    ('0466c65a-a37a-57b9-b17b-1e4acbc6a934'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, '« El color » est masculin en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que le français hésite : la couleur est féminine.', 7),
    ('84395225-7bcf-5c1d-9a41-89bc215b7eb8'::uuid, '4e9513b5-d372-5367-a7e4-01762d64387e'::uuid, 'Comment se forme le pluriel après une consonne ?', 'mcq', '["On ajoute -es","On ajoute -s","On ne change rien","On double la consonne"]'::jsonb, 0, '*Papel → papeles*, *ciudad → ciudades*.', 8),
    ('3f95dd5f-df12-5a58-b3b8-24f356ae495b'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, 'Quelles sont les deux contractions de l’espagnol ?', 'mcq', '["Al et del","Al, del et col","Del seulement","Al, del, pel"]'::jsonb, 0, '*a + el = al*, *de + el = del*.', 1),
    ('7ee3e5ab-67d1-5261-8899-907212e73127'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, 'Pourquoi dit-on « el agua » ?', 'mcq', '["Le nom féminin commence par un a- tonique","Le nom est masculin","C’est une exception isolée","L’article est neutre"]'::jsonb, 0, 'Le mot reste féminin : *el agua fría*, *las aguas*.', 2),
    ('6d57533b-12ac-5b6c-a9fc-dddd36fdc9c8'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, '« El agua » devient « los aguas » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le pluriel reprend l’article féminin : *las aguas*.', 3),
    ('abaf5ea0-00c8-5d2f-b457-19234dc6d474'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, 'Que précède l’article neutre « lo » ?', 'mcq', '["Un adjectif, un adverbe ou un relatif","Un nom masculin","Un nom féminin","Un verbe"]'::jsonb, 0, '*Lo importante*, *lo mejor*, *lo que dices*.', 4),
    ('de13f3b2-2bec-5df9-a2b6-c0e705ed60f8'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, 'Comment dit-on « je suis professeur » ?', 'mcq', '["Soy profesor","Soy un profesor","Estoy profesor","Soy el profesor"]'::jsonb, 0, 'Pas d’article devant une profession attribut, sauf si elle est qualifiée.', 5),
    ('e4a23837-181c-5cb3-8c8a-2bb617a20e86'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, '« Unos amigos » signifie « quelques amis ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pluriel de l’indéfini exprime l’approximation.', 6),
    ('d0bc1e17-b2fa-5098-bc68-acbf32ae4475'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, 'Comment traduire « un autre jour » ?', 'mcq', '["Otro día","Un otro día","El otro día","Uno otro día"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 7),
    ('b9116949-f060-5c44-b2f5-f044a0363150'::uuid, 'd08e27a2-97ad-5844-8ade-8fa94c4b5918'::uuid, '« La avenida » ne prend pas « el » parce que…', 'mcq', '["L’accent tonique ne tombe pas sur le a initial","Le mot est masculin","Le mot est pluriel","Le mot est étranger"]'::jsonb, 0, 'La règle ne vaut que pour un a- ou ha- TONIQUE.', 8),
    ('147043c7-d815-5168-97f6-bafdd39142cc'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, 'Combien l’espagnol a-t-il de séries de démonstratifs ?', 'mcq', '["Trois : este, ese, aquel","Deux : este et ese","Une seule","Quatre"]'::jsonb, 0, 'Elles correspondent à *aquí*, *ahí*, *allí*.', 1),
    ('5ba2ab7e-6839-5505-8e0a-38e3951e027a'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, 'Quel démonstratif désigne ce qui est près de l’interlocuteur ?', 'mcq', '["Ese","Este","Aquel","Esto"]'::jsonb, 0, '*Ese libro que tienes en la mano.*', 2),
    ('7168d3d0-bac8-52b4-aec6-dca04456eac3'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, 'Les démonstratifs neutres « esto, eso, aquello » sont invariables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et ils ne sont jamais suivis d’un nom.', 3),
    ('152c6677-e548-5771-a477-c2d4c2b2a6ea'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, 'Comment reprendre une phrase entière ?', 'mcq', '["Par un neutre : eso","Par ese","Par esta","Par aquellos"]'::jsonb, 0, '*No vino, y eso me molestó.*', 4),
    ('29d930a1-52e7-55dd-b4b9-e1f1e7f400d9'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, 'Depuis 2010, le pronom démonstratif porte un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La RAE l’a supprimé : on écrit *este* pronom comme *este* adjectif.', 5),
    ('705500c8-243b-5f8f-beba-068fa9c6d719'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, '« Aquellos tiempos » évoque…', 'mcq', '["Une époque lointaine","L’instant présent","Le futur proche","La semaine dernière"]'::jsonb, 0, '*Aquel* marque la plus grande distance, y compris temporelle.', 6),
    ('a1307b32-c42d-5b75-bb81-c9bae1a7eae3'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, 'Comment traduire « qu’est-ce que c’est ? » ?', 'mcq', '["¿Qué es esto?","¿Qué es este?","¿Qué es ésta?","¿Qué es aquel?"]'::jsonb, 0, 'La chose n’étant pas identifiée, on emploie le neutre.', 7),
    ('41a7e4fb-7867-5818-bb92-e3433caf4920'::uuid, 'f0a826d2-28ad-5e7c-a977-b9c1ecb81cb6'::uuid, '« Esta » et « estas » sont les formes féminines de « este ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin : *este / estos* ; féminin : *esta / estas*.', 8),
    ('f90de374-9a3d-567c-bb48-c9636d8fb550'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, 'Où se place l’adjectif espagnol par défaut ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Avant le verbe"]'::jsonb, 0, 'C’est la position qui classe objectivement : *un coche rojo*.', 1),
    ('cadf4661-4522-58dc-a6f7-fa8762a26aba'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, '« Un gran hombre » et « un hombre grande » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier est un grand homme, le second un homme de grande taille.', 2),
    ('1e874041-68e3-56fd-b475-fca36a8adfb0'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, 'Quel adjectif a quatre formes ?', 'mcq', '["Alto (alto, alta, altos, altas)","Inteligente","Fácil","Verde"]'::jsonb, 0, 'Les adjectifs en -e ou en consonne sont invariables en genre.', 3),
    ('c9ced51d-3d38-582f-80db-651e973f517a'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, '« Un chico y una chica simpáticos » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des noms de genres différents, l’adjectif se met au masculin pluriel.', 4),
    ('a1b59acd-9d11-5b7e-8685-2b3b6d62a1c2'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, 'Que signifie « un pobre hombre » ?', 'mcq', '["Un homme à plaindre","Un homme sans argent","Un homme humble","Un homme malade"]'::jsonb, 0, 'Placé après, *un hombre pobre* désigne la pauvreté matérielle.', 5),
    ('ba6afec0-8f88-50d9-b108-04611c5c5f13'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, 'Les adjectifs de nationalité forment un féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Español/española*, *inglés/inglesa*, même s’ils finissent par une consonne.', 6),
    ('1e81185f-8953-5421-9444-562fcb26e352'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, '« Un viejo amigo » signifie…', 'mcq', '["Un ami de longue date","Un ami âgé","Un ancien ami fâché","Un ami d’enfance uniquement"]'::jsonb, 0, 'La place avant le nom porte l’appréciation, pas l’âge.', 7),
    ('c87a9771-5f14-5cbd-84b3-6adf7ced5f9a'::uuid, '9b640a21-675a-5ca5-9b07-a9835f03d708'::uuid, 'Un adjectif placé avant le nom exprime souvent une appréciation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La blanca nieve*, *un buen amigo* : le regard de celui qui parle.', 8),
    ('1291dea3-5672-50f4-9c02-05ea7a3982ee'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, 'Pourquoi l’espagnol omet-il souvent le pronom sujet ?', 'mcq', '["La terminaison du verbe identifie déjà la personne","C’est un usage familier","Pour aller plus vite","Le pronom n’existe pas"]'::jsonb, 0, 'On l’exprime pour insister, opposer ou lever une ambiguïté.', 1),
    ('ff5284c7-7c06-5a67-8644-40e52583a933'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, '« Usted » se conjugue à la deuxième personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'À la troisième : *¿Usted habla español?* — il vient de *vuestra merced*.', 2),
    ('72e2702f-e949-5627-b133-bf0f9003f771'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, 'Quel pronom remplace « vosotros » en Amérique latine ?', 'mcq', '["Ustedes","Vos","Tú","Nosotros"]'::jsonb, 0, '*Vosotros* n’y est pas employé, même entre amis.', 3),
    ('23c02fab-4795-5433-a424-f9a9301582d8'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, 'Le « voseo » consiste à employer…', 'mcq', '["Vos à la place de tú","Usted à la place de tú","Vosotros à la place d’ustedes","Nos à la place de nosotros"]'::jsonb, 0, '*Vos tenés*, *vos sos* : norme d’Argentine, d’Uruguay, du Paraguay.', 4),
    ('fb818f60-6363-5824-8946-312b3813c51a'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, 'Comment traduire « pour moi » ?', 'mcq', '["Para mí","Para yo","Por yo","Para me"]'::jsonb, 0, 'Après préposition, *yo* devient *mí* et *tú* devient *ti*.', 5),
    ('1683ad8a-88cc-5622-8317-f6eb3de65ea4'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, '« Conmigo » et « contigo » sont des formes soudées irrégulières.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne dit jamais « con mí » ni « con ti ».', 6),
    ('c9500532-2923-5f96-ae9d-b291d298c565'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, 'Après « entre » et « según », quel pronom emploie-t-on ?', 'mcq', '["Tú et yo","Ti et mí","Te et me","Usted seulement"]'::jsonb, 0, '*Entre tú y yo*, *según tú* : ces prépositions font exception.', 7),
    ('aaeceb0d-bdb5-59f7-b134-db6bf11c8994'::uuid, '660a0f05-ff09-51d3-a50e-957f0a715ce9'::uuid, '« Yo no lo he dicho » exprime une insistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans le *yo*, la phrase serait neutre : le pronom souligne le contraste.', 8),
    ('ddd0de09-fb72-524b-8bf4-ec319e08bd78'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, 'Dans quel ordre se placent les pronoms compléments ?', 'mcq', '["COI puis COD","COD puis COI","Selon la longueur du mot","Indifféremment"]'::jsonb, 0, '*Me lo da*, *te la doy* : le COI passe toujours devant.', 1),
    ('57b3bec4-9f1a-52ad-8f9a-59108471369c'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, 'Que devient « le » devant « lo » ?', 'mcq', '["Se","Lo","La","Les"]'::jsonb, 0, '*Se lo doy* : « le lo doy » n’existe pas.', 2),
    ('711561fc-7d94-5da3-aa29-5bea05fadaa8'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, 'Avec un impératif affirmatif, le pronom se soude derrière le verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dámelo*, *dímelo* — et l’accent écrit apparaît.', 3),
    ('4fcf05bd-33bb-5b17-9ca2-dfef7d2e076e'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, 'Où se place le pronom avec un impératif négatif ?', 'mcq', '["Devant le verbe","Soudé derrière","Après le sujet","En fin de phrase"]'::jsonb, 0, '*No me lo des* : l’enclise ne vaut que pour l’affirmatif.', 4),
    ('2782e775-d8a5-5b82-a81c-72e29d04b8c8'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, '« Voy a decírtelo » et « Te lo voy a decir » sont tous deux corrects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec un verbe conjugué + infinitif, les deux placements sont admis.', 5),
    ('4d057a75-39c7-5369-bbd8-3541553c9303'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, 'Quel pronom COD correspond à « la » (féminin) ?', 'mcq', '["La","Le","Se","Ella"]'::jsonb, 0, '*La veo* : je la vois. *Le hablo* serait un COI.', 6),
    ('130fd4c4-b622-5937-9c95-4b0b78021f0a'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, 'Le redoublement du COI est une lourdeur à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : *Le doy el libro a Juan*, *A mí me gusta*.', 7),
    ('9d9256cd-252e-545c-8bbd-ad68fc5d0ea1'::uuid, '0182bce9-fe7d-585e-bd52-819f2c1e7ac8'::uuid, 'L’accent écrit sur « dámelo » sert à…', 'mcq', '["Conserver la syllabe tonique du verbe d’origine","Marquer l’impératif","Distinguer le COD du COI","Signaler un pluriel"]'::jsonb, 0, 'L’enclise allonge le mot : sans accent, la prononciation changerait.', 8),
    ('e30f8ce1-def6-5590-8805-c5694e8631a3'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, 'Avec quoi le possessif espagnol s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Avec l’article"]'::jsonb, 0, '*Mis libros* : le -s vient des livres, pas de moi.', 1),
    ('61928292-c665-508c-9273-14e03f340a28'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, 'Comment traduire « je me lave les mains » ?', 'mcq', '["Me lavo las manos","Me lavo mis manos","Lavo mis manos","Me lavo mías manos"]'::jsonb, 0, 'Corps et vêtements prennent l’article défini, pas le possessif.', 2),
    ('e69b3ef9-0962-543d-a152-c567a91e416b'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, '« Su » peut signifier son, sa, leur ou votre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le recours à *de él*, *de usted* pour lever l’ambiguïté.', 3),
    ('8cfe7d08-929d-5ee2-bb5f-de588f798efa'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, 'Comment dit-on « un ami à moi » ?', 'mcq', '["Un amigo mío","Un mi amigo","Un amigo de mí","Mi un amigo"]'::jsonb, 0, 'La forme tonique se place après le nom.', 4),
    ('3a8f902d-7f3c-5d0d-a576-3e63e9720376'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, 'Quelles formes atones varient en genre ?', 'mcq', '["Nuestro et vuestro","Mi et tu","Su seulement","Toutes"]'::jsonb, 0, '*Nuestra casa*, *vuestros libros* — mais *mi* et *tu* restent invariables.', 5),
    ('7e6d66d9-b378-59c0-a6c3-7a6a19e4f5c4'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, '« El mío » est un pronom possessif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article + forme tonique : *El mío es más grande.*', 6),
    ('e2af0672-a053-5803-a2cb-6e71b3da2910'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, 'Comment traduire « il a mal à la tête » ?', 'mcq', '["Le duele la cabeza","Le duele su cabeza","Duele su cabeza","Tiene mal su cabeza"]'::jsonb, 0, 'Le pronom *le* porte déjà l’information de possession.', 7),
    ('67afba92-c190-54e2-95c2-af10acc3cfb7'::uuid, '738dc861-3713-51e6-813e-39f74536c539'::uuid, 'Au vocatif, on dit « ¡Hijo mío! ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme tonique suit le nom en apostrophe : *¡Madre mía!*', 8),
    ('8677d050-a9c5-5154-84ef-15016c7f2708'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, 'Avec quoi « cuyo » s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Il est invariable"]'::jsonb, 0, '*El escritor cuya novela leí* : *cuya* s’accorde avec *novela*.', 1),
    ('3b31ff5a-efa5-5b41-9369-4db97a27f257'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, '« Cuyo » peut être suivi d’un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Cuyo el libro » n’existe pas : *cuyo libro* directement.', 2),
    ('00080220-9fec-5b83-a4c6-ecf7910589d6'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, 'Quel relatif s’emploie uniquement pour des personnes ?', 'mcq', '["Quien","Que","Cuyo","Donde"]'::jsonb, 0, '*La persona con quien hablo.*', 3),
    ('e76e91cf-282d-519f-a6a5-e1ba232b7058'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo","La casa cuya vivo","La casa quien vivo"]'::jsonb, 0, 'Après préposition, *que* prend l’article.', 4),
    ('e8b829d4-fdf4-523c-879c-976c35cddbd3'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, 'Pour reprendre une idée entière, on emploie « lo que » ou « lo cual ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 5),
    ('2b2ff67f-11b2-5a23-a1bf-f40b02c92bd8'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, '« Los que quieran, que vengan » signifie…', 'mcq', '["Que ceux qui veulent viennent","Ceux-là veulent venir","Ils veulent qu’ils viennent","Que veulent-ils venir"]'::jsonb, 0, '*El que / los que* sans antécédent = celui qui / ceux qui.', 6),
    ('8602d9bf-6bc5-5d02-82e9-17e5ae30fab4'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, 'Comment demander « à qui est-ce ? »', 'mcq', '["¿De quién es?","¿Cuyo es?","¿Que es de?","¿Quien es de?"]'::jsonb, 0, '*Cuyo* ne s’emploie jamais dans une question.', 7),
    ('80cd8c9e-ce3e-5dc1-8251-d193adffdc0b'::uuid, 'ae2cf542-18b5-5b5e-a762-16b0ff361b16'::uuid, '« El cual » appartient à un registre plus soutenu que « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Surtout après une préposition longue : *la razón por la cual*.', 8),
    ('1b7231d6-53dd-50a0-96e5-0d9ba1fce6ea'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, 'Comment traduire « je ne vois personne » ?', 'mcq', '["No veo a nadie","No veo nadie","Veo a nadie","No veo alguien"]'::jsonb, 0, 'Double négation, et le *a* devant un COD de personne.', 1),
    ('4faf1990-ac86-52f4-9cb7-47e31cbd8168'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, '« Cualquiera » s’apocope en « cualquier » devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin comme féminin : *cualquier día*, *cualquier mujer*.', 2),
    ('ec79a999-8846-5431-b081-298927e72814'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, '« Cada » peut-il se mettre au pluriel ?', 'mcq', '["Non, il est invariable","Oui : cadas","Oui au féminin seulement","Oui devant un nombre"]'::jsonb, 0, '*Cada día*, *cada dos horas* ; « chacun » se dit *cada uno*.', 3),
    ('41dd03e1-9c63-5792-a3e3-6d3e6e33e4f1'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, 'Placé après le nom, « alguno » prend un sens…', 'mcq', '["Négatif renforcé","Positif renforcé","Interrogatif","Neutre"]'::jsonb, 0, '*No tengo duda alguna* = aucun doute.', 4),
    ('e464b4f4-f6dd-5d60-bc20-844a3a3e6397'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, '« Todos días » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Todo* exige l’article : *todos los días*.', 5),
    ('112a6828-cbfa-54be-8ac8-9e2575c73109'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, 'Que signifie « los demás » ?', 'mcq', '["Les autres, le reste","Les mêmes","Trop nombreux","Chacun"]'::jsonb, 0, '*Los demás alumnos se fueron.*', 6),
    ('b38f3193-edc6-5b0c-b630-fa0df0852546'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, '« Alguien » et « nadie » sont invariables et toujours singuliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ne s’accordent ni en genre ni en nombre.', 7),
    ('9908e2e4-2d0e-5425-aca5-79f7b3340d73'::uuid, '252278a1-2d60-591b-9878-e25407ba25f4'::uuid, 'Comment dit-on « un autre livre » ?', 'mcq', '["Otro libro","Un otro libro","El otro libro","Otro el libro"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 8),
    ('c97177ac-6042-542d-a138-5acc8fb8ce36'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, 'Comment traduire « aussi grand que toi » ?', 'mcq', '["Tan alto como tú","Tanto alto como tú","Más alto como tú","Tan alto que tú"]'::jsonb, 0, '*Tan* devant un adjectif, *como* comme second terme.', 1),
    ('82e912a0-60c2-5972-9657-b2512700437e'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, 'Comment traduire « autant de livres que toi » ?', 'mcq', '["Tantos libros como tú","Tan libros como tú","Tanto libros como tú","Más libros como tú"]'::jsonb, 0, '*Tanto* devant un nom, et il s’accorde : *tantos libros*.', 2),
    ('68ccd5d3-8fdb-521b-a1cd-43f7604cc7b5'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, 'Devant un nombre, on emploie « de » et non « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Más de veinte libros*, *menos de diez euros*.', 3),
    ('55b46dd1-7db9-5e77-b6ec-c6ed684d3098'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, 'Que signifie « No tengo más que diez euros » ?', 'mcq', '["Je n’ai que dix euros","Je n’ai pas plus de dix euros","J’ai plus de dix euros","J’ai environ dix euros"]'::jsonb, 0, 'En phrase négative, *más que* signifie « seulement ».', 4),
    ('6081f978-e463-550e-8222-2babfe81c7a2'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, '« Más mejor » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les comparatifs irréguliers ne se combinent jamais avec *más*.', 5),
    ('f8a33297-938d-5338-8dc1-2f67a2763748'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, 'Quel est le comparatif de « malo » ?', 'mcq', '["Peor","Más malo","Menor","Mal"]'::jsonb, 0, 'Comme *bueno → mejor*, *grande → mayor*, *pequeño → menor*.', 6),
    ('272dece0-315f-5fc7-bc6b-11a790943fc1'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, 'Comment traduire « plus difficile qu’il n’y paraît » ?', 'mcq', '["Más difícil de lo que parece","Más difícil que parece","Más difícil como parece","Tan difícil que parece"]'::jsonb, 0, 'Quand le second terme est une proposition : *de lo que*.', 7),
    ('3cce9e19-d7b3-55d2-abf2-5bd20d3be441'::uuid, '7d083316-4072-55c0-b260-b02e1a9bb2f0'::uuid, '« Trabaja tanto como yo » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un verbe, on emploie *tanto como*, invariable.', 8),
    ('70ccf778-b0fd-5faf-a716-469da69db888'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, 'Comment traduire « le plus grand du monde » ?', 'mcq', '["El más grande del mundo","El más grande en el mundo","El mucho grande del mundo","El más grande que el mundo"]'::jsonb, 0, 'Le complément du superlatif relatif se construit avec *de*.', 1),
    ('1bb9b48e-0a14-5bc0-9b6c-b5186da4237b'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, '« Muy guapísimo » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie *muy* OU le suffixe -ísimo, jamais les deux.', 2),
    ('48c8af0a-32e3-58af-8cf8-f79d451fe75d'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, 'Quel est le superlatif absolu de « rico » ?', 'mcq', '["Riquísimo","Ricísimo","Rikísimo","Ricoísimo"]'::jsonb, 0, 'Le c devient qu pour conserver le son [k].', 3),
    ('fe0787b8-8990-55a7-9b1d-0cc76879a027'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, 'Quel est le superlatif absolu de « feliz » ?', 'mcq', '["Felicísimo","Felizísimo","Felisísimo","Felizmo"]'::jsonb, 0, 'Le z devient c devant le i.', 4),
    ('b67b7480-d98e-5f90-8ad4-52f608466204'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, '« Óptimo » est le superlatif savant de « bueno ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *pésimo* pour *malo*, *máximo* pour *grande*.', 5),
    ('e8977dd2-47ef-596a-b8f3-721b890f4b07'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, 'Que devient le « g » de « largo » au superlatif ?', 'mcq', '["Il devient gu : larguísimo","Il disparaît","Il devient j","Il double"]'::jsonb, 0, 'Pour conserver le son [g] devant le i.', 6),
    ('0dae8210-bc35-55bc-8953-49bba8da2486'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, 'Le superlatif relatif compare à l’intérieur d’un ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El alumno más inteligente de la clase* : l’ensemble est la classe.', 7),
    ('70df5d79-e215-5fdc-8971-f6abe2e43934'::uuid, '1688fb08-a172-5192-84e9-f816f1b40be5'::uuid, 'Comment dit-on « énormément » avec un suffixe ?', 'mcq', '["Muchísimo","Muy mucho","Mucho muy","Máximo"]'::jsonb, 0, '*Mucho* prend lui aussi le suffixe -ísimo.', 8),
    ('9a306656-b3b2-5c01-9768-a671fa21d050'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, 'Quelle est la forme apocopée de « bueno » devant un nom masculin ?', 'mcq', '["Buen","Bue","Buenó","Bon"]'::jsonb, 0, '*Un buen amigo*, mais *un amigo bueno* garde la forme pleine.', 1),
    ('9bc3be67-dae1-53a8-98fa-f3ee5e66b580'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, '« Grande » s’apocope devant un nom féminin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Una gran mujer* : c’est le seul adjectif à s’apocoper aux deux genres.', 2),
    ('122ebff8-6279-5e57-b8cc-09de8d855b6d'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, 'Comment dit-on « cent euros » ?', 'mcq', '["Cien euros","Ciento euros","Cientos euros","Cien de euros"]'::jsonb, 0, '*Ciento* s’apocope devant un nom, et devant *mil* et *millones*.', 3),
    ('d6ebf1e8-8932-52ba-ab9b-492f3c2d9a64'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, 'Quelle est la forme correcte : « santo Domingo » ou « Santo Domingo » ?', 'mcq', '["Santo Domingo : pas d’apocope devant To- et Do-","San Domingo","Sant Domingo","Sa Domingo"]'::jsonb, 0, 'Même exception pour *Santo Tomás* et *Santo Tomé*.', 4),
    ('10a7ea65-e443-519d-9aeb-4729c867b94d'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, '« Tercero » devient « tercer » devant un nom masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El tercer año*, comme *el primer piso*.', 5),
    ('a7406c51-9710-56ac-9033-075f2bd1283c'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, 'Quelle est la forme apocopée de « cualquiera » ?', 'mcq', '["Cualquier, aux deux genres","Cualqui","Cualquiero","Il ne s’apocope pas"]'::jsonb, 0, '*Cualquier día*, *cualquier mujer*.', 6),
    ('f555ed15-310d-52a4-95e2-a82b7d0ccba8'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, '« Recién » s’emploie devant un participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Recién nacido*, *recién llegado*, *recién casados*.', 7),
    ('4ca3d7c8-3ddf-535d-a354-49f4eb048ec9'::uuid, 'f40be6ee-4c70-5fa8-bcd8-4634348c1491'::uuid, '« Ciento veinte » garde la forme pleine parce que…', 'mcq', '["Ciento est suivi d’un autre nombre","Ciento est féminin","Le nombre est pair","Il s’agit d’un pluriel"]'::jsonb, 0, 'L’apocope ne joue que devant un nom, *mil* ou *millones*.', 8),
    ('2c53cf68-b83d-5e00-bbcf-f1dd53daf36e'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, 'Combien l’espagnol a-t-il d’auxiliaires de temps composés ?', 'mcq', '["Un seul : haber","Deux : haber et ser","Deux : haber et tener","Trois"]'::jsonb, 0, 'Contrairement au français, aucune hésitation entre « être » et « avoir ».', 1),
    ('089fa58e-01a7-55a4-bdbd-907d807696e1'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, 'Le participe passé s’accorde avec « haber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais : *la carta que he escrito*, *ellas han venido*.', 2),
    ('69e5f050-00f1-5e9a-a4e3-de04db1ed455'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, 'Comment traduire « il y a deux livres » ?', 'mcq', '["Hay dos libros","Han dos libros","Hays dos libros","Están dos libros"]'::jsonb, 0, '*Hay* est invariable, même devant un pluriel.', 3),
    ('d3e9b31e-e763-5e72-b241-6759f2d6c647'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, 'Peut-on placer un adverbe entre l’auxiliaire et le participe ?', 'mcq', '["Non, le bloc est soudé","Oui, toujours","Oui, si c’est une négation","Oui, à l’écrit seulement"]'::jsonb, 0, '*No lo he visto nunca*, jamais « he nunca visto ».', 4),
    ('453505c0-c062-5cf7-ac8f-ee8d05897d8f'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, '« Había » est la forme passée de « hay ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et elle reste au singulier : *Había muchos alumnos.*', 5),
    ('9fad6b33-9a52-5385-92cb-4ba22e49c20b'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, 'Que signifie « Hay que estudiar » ?', 'mcq', '["Il faut étudier","J’ai étudié","Il y a des études","Il faut que j’étudie"]'::jsonb, 0, 'Obligation impersonnelle, sans sujet exprimé.', 6),
    ('248187c1-7dc3-519a-a543-f9eddccc61d7'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Había + participe passé","Hubo + participe passé","Era + participe passé","Estaba + participe passé"]'::jsonb, 0, '*Había salido cuando llegué.*', 7),
    ('73d49d5c-03a4-5061-9454-53bc95e0316c'::uuid, '43fca079-34fc-5bcd-a438-b84d7657569f'::uuid, '« Hay un banco en la plaza » et « El banco está en la plaza » disent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Hay* pose l’existence, *estar* localise une chose déjà connue.', 8),
    ('4b1b1675-0fc6-511b-bd71-e40f8f13cb82'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, 'Où se place le pronom réfléchi avec un infinitif ?', 'mcq', '["Soudé derrière : levantarse","Devant l’infinitif","En fin de phrase","Devant le sujet"]'::jsonb, 0, 'Même chose au gérondif et à l’impératif affirmatif.', 1),
    ('bdc6f713-26f1-5feb-a20d-fd6ba15c1813'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, 'Dans « Se venden pisos », le verbe s’accorde avec « pisos ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un *se* passif : le sujet grammatical est *pisos*.', 2),
    ('9f26f2bb-dfd9-5683-b853-74acb4196c55'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, 'Que signifie « Me voy » ?', 'mcq', '["Je m’en vais","Je vais bien","Je me vois","Je viens"]'::jsonb, 0, '*Ir* signifie aller, *irse* partir : le pronom change le sens.', 3),
    ('f1d27af3-0e2a-5359-a216-4213a8099155'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, 'Dans un « se » impersonnel, le verbe est…', 'mcq', '["Toujours au singulier","Toujours au pluriel","Accordé au complément","À l’infinitif"]'::jsonb, 0, '*Se dice que…*, *Aquí se come bien.*', 4),
    ('a7804c89-13d1-5dce-9ef8-a9fb2b766995'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, '« Quejarse » et « atreverse » sont des verbes essentiellement pronominaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pronom fait partie du verbe : il n’a pas de valeur réfléchie.', 5),
    ('b79e499f-64fe-5eca-a205-8d6371dfaad7'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, 'Que signifie « Se escriben » ?', 'mcq', '["Ils s’écrivent l’un à l’autre","Ils s’écrivent eux-mêmes","On les écrit","Ils sont écrits"]'::jsonb, 0, 'Valeur réciproque : plusieurs sujets agissent l’un sur l’autre.', 6),
    ('bcd66a40-c785-53c7-839b-7621f4f4cae0'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, '« Dormirse » signifie « s’endormir ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que *dormir* signifie simplement dormir.', 7),
    ('159c3dff-4447-5c6d-ac43-f58d6edb78e3'::uuid, '6d25a289-91ac-55ee-a2c3-eb488128a3ff'::uuid, 'Dans « Se comió toda la tarta », le pronom exprime…', 'mcq', '["Une nuance d’appropriation","Une réciprocité","Une passive","Une obligation"]'::jsonb, 0, 'Le pronominal d’intensité, sans valeur réfléchie.', 8),
    ('91ad28b2-43bb-5eed-9e86-d9fa33d8d608'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, 'Qu’est-ce qui déclenche la diphtongue ?', 'mcq', '["L’accent tonique sur la voyelle du radical","La terminaison en -ar","Le pluriel","La négation"]'::jsonb, 0, 'Quand l’accent passe sur la terminaison, la voyelle redevient simple.', 1),
    ('1dd38274-c526-525d-881b-09fde3b7fc83'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, 'Quelles personnes ne diphtonguent jamais ?', 'mcq', '["Nosotros et vosotros","Yo et tú","Él et ellos","Tú et vosotros"]'::jsonb, 0, 'Elles portent l’accent sur la terminaison : d’où la conjugaison « en botte ».', 2),
    ('2ef6db2a-17fd-52cc-baa1-812f6c4e5173'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, 'Quelle est la première personne de « poder » au présent ?', 'mcq', '["Puedo","Podo","Puedo/podo","Puedes"]'::jsonb, 0, 'La diphtongue o → ue apparaît sous l’accent.', 3),
    ('3627b9dd-42bd-5e25-85ad-27720f72d108'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, '« Jugar » est le seul verbe à diphtonguer u → ue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Juego, juegas, juega… jugamos, jugáis, juegan.*', 4),
    ('202d256a-60e1-5a32-8225-7e206ec0e310'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, 'La diphtongue apparaît aussi au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seulement au présent de l’indicatif, au subjonctif présent et à l’impératif.', 5),
    ('09a32ef6-2ca7-5184-a738-8e4cb010643d'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, 'Quelle est la forme de « pensar » à la première personne du pluriel ?', 'mcq', '["Pensamos","Piensamos","Pensemos","Piensemos"]'::jsonb, 0, 'L’accent tombe sur la terminaison : pas de diphtongue.', 6),
    ('9748c587-fe39-5124-a1c9-62d74ea2d7bb'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, 'Que devient « oler » quand il diphtongue ?', 'mcq', '["Huelo, avec un h","Uelo","Ólo","Oigo"]'::jsonb, 0, 'Un h purement orthographique s’ajoute devant le ue initial.', 7),
    ('cda26d24-d6b1-53e2-9018-651513e781de'::uuid, '654b322e-11ff-5402-be5b-e51254ef5b6b'::uuid, '« Pedir → pido » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un verbe à affaiblissement : le e devient i, il ne diphtongue pas.', 8),
    ('30033335-4061-5726-aa26-8c6bae771958'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, 'À quel groupe appartiennent tous les verbes à affaiblissement ?', 'mcq', '["Aux verbes en -ir","Aux verbes en -ar","Aux verbes en -er","À tous les groupes"]'::jsonb, 0, '*Pedir, servir, repetir, seguir…* — aucun -ar ni -er.', 1),
    ('70c22528-f041-563c-8b25-ea67cb963aa0'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, 'Quelle est la troisième personne du passé simple de « pedir » ?', 'mcq', '["Pidió","Pedió","Pidó","Pediró"]'::jsonb, 0, 'Dès que la terminaison contient un ió ou un ie, le e s’affaiblit.', 2),
    ('fa8c04fc-2291-505a-aae6-7ed5749e008f'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, 'Au subjonctif présent, l’affaiblissement touche toutes les personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pida, pidas, pida, pidamos, pidáis, pidan* — y compris nosotros et vosotros.', 3),
    ('516b4875-db83-5a7a-b918-902815da2f9e'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, 'Quel est le gérondif de « decir » ?', 'mcq', '["Diciendo","Deciendo","Diciento","Dicendo"]'::jsonb, 0, 'Le gérondif des verbes en -ir irréguliers porte l’affaiblissement.', 4),
    ('7c4e7489-36c1-5c1d-bea5-52c7666c87d8'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, '« Dormir » est un verbe mixte : diphtongue au présent, affaiblissement ailleurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Duermo* au présent, mais *durmió* et *durmiendo*.', 5),
    ('78ce01ee-1de4-5af2-8436-34a4c093d6e1'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, 'Quelle est la première personne du présent de « seguir » ?', 'mcq', '["Sigo","Siguo","Sego","Seguo"]'::jsonb, 0, 'Le u disparaît devant o et a, sinon il se prononcerait.', 6),
    ('6bd68ccf-b6e5-5d3c-8930-0a2a452ee4ac'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, 'Que devient le « g » de « elegir » devant un o ?', 'mcq', '["Il devient j : elijo","Il devient gu","Il disparaît","Il double"]'::jsonb, 0, 'Pour conserver le son [x] : *elijo*, *corrijo*.', 7),
    ('5e60b8a7-4cda-5f9e-8c4c-c3b81b7120cc'::uuid, '26e8eb08-09bc-50d2-ace5-1bde02e62a12'::uuid, '« Pedimos » porte l’affaiblissement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme *pedís*, il garde le e : l’accent tombe sur la terminaison.', 8),
    ('3f81722e-d9fc-5f5b-9349-7d403bf042fe'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, 'Quel verbe employer pour la localisation d’une chose ?', 'mcq', '["Estar","Ser","Haber","Tener"]'::jsonb, 0, '*Madrid está en España* — mais un événement se situe avec *ser*.', 1),
    ('368d9d92-fac5-5cde-b281-221d44eb4c9c'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, '« Ser listo » et « estar listo » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Être malin » contre « être prêt » : deux mots différents.', 2),
    ('5da106c0-c027-5d37-93a3-25bdb284d4f8'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, 'Comment dit-on l’heure en espagnol ?', 'mcq', '["Son las tres","Están las tres","Hay las tres","Tienen las tres"]'::jsonb, 0, 'Heure, date, prix : toujours *ser*.', 3),
    ('3e7ed083-12ef-583a-8d78-f224f4a90175'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, 'Que signifie « estar malo » ?', 'mcq', '["Être malade","Être méchant","Être mauvais","Être en colère"]'::jsonb, 0, '*Ser malo* signifie être méchant.', 4),
    ('07254795-a738-580e-902e-e24dd414c202'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, '« La fiesta es en mi casa » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un événement se situe avec *ser*, à la différence d’un lieu ou d’un objet.', 5),
    ('9597dec0-44cc-5941-87a4-3e2fa6a70578'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, 'Quel verbe entre dans la forme progressive ?', 'mcq', '["Estar (estoy estudiando)","Ser","Haber","Ir"]'::jsonb, 0, '*Estar* + gérondif exprime l’action en cours.', 6),
    ('d1fa50a5-50dd-56f8-af09-612419e4ac61'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, '« La sopa está fría » décrit un état constaté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La soupe a refroidi ; *el hielo es frío* énonce une propriété.', 7),
    ('8813088f-7d32-5f04-a12a-881b98e8397b'::uuid, '7f97862d-9e53-5135-8744-86f6164ce6d2'::uuid, 'Comment dit-on « je suis d’accord » ?', 'mcq', '["Estoy de acuerdo","Soy de acuerdo","Tengo de acuerdo","Hay de acuerdo"]'::jsonb, 0, 'Expression figée avec *estar*, comme *estar de vacaciones*.', 8),
    ('7151b520-a984-5cca-b5af-05be25298a37'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, 'Quelle est la terminaison du gérondif des verbes en -ar ?', 'mcq', '["-ando","-iendo","-yendo","-ado"]'::jsonb, 0, '*Hablar → hablando* ; les -er et -ir font *-iendo*.', 1),
    ('91cd4b9f-d935-5726-93e3-b53be82f7447'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, 'Quel est le gérondif de « leer » ?', 'mcq', '["Leyendo","Leiendo","Leendo","Leído"]'::jsonb, 0, 'Le -iendo devient -yendo après une voyelle.', 2),
    ('f6f43534-129d-5285-9fe3-9fc42a108e67'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, '« Una caja conteniendo libros » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le gérondif ne qualifie pas un nom : *una caja que contiene libros*.', 3),
    ('5f748453-9bed-5a33-91b4-19d01958089b'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, 'Que signifie « Llevo dos años estudiando español » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié deux ans","J’emporte deux ans d’espagnol","Je vais étudier deux ans"]'::jsonb, 0, '*Llevar* + durée + gérondif exprime la durée écoulée.', 4),
    ('e5318ec0-7fe2-5fda-8a9d-5fd820dea5a0'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, 'Après une préposition, on emploie l’infinitif et non le gérondif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Antes de salir*, *sin decir nada*, *al entrar*.', 5),
    ('230146ec-d6b9-5332-9a5d-a199b06415c8'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, 'Comment traduire « en entrant, j’ai vu Juan » ?', 'mcq', '["Al entrar, vi a Juan","Entrando, vi a Juan","En entrando, vi a Juan","Para entrar, vi a Juan"]'::jsonb, 0, '*Al* + infinitif exprime la simultanéité.', 6),
    ('d6977710-b7ef-50aa-9b49-05476f9c5041'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, '« Sigue lloviendo » signifie « il pleut toujours ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Seguir* + gérondif exprime la continuation.', 7),
    ('e1f505c6-2a5f-5bb3-850b-306a87c52f09'::uuid, 'b80678fc-c8b2-593c-9b0a-aaefa326d4d4'::uuid, 'Quel est le gérondif de « dormir » ?', 'mcq', '["Durmiendo","Dormiendo","Duermiendo","Durmendo"]'::jsonb, 0, 'L’affaiblissement o → u apparaît au gérondif des verbes en -ir.', 8),
    ('b91a10dc-9bf5-5de7-9a23-c30a4363d38b'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'Le participe employé avec « haber » s’accorde-t-il ?', 'mcq', '["Jamais","Toujours","Seulement au féminin","Seulement au pluriel"]'::jsonb, 0, '*Ellas han llegado*, *las cartas que he escrito*.', 1),
    ('149553c0-7acd-597d-83ab-40de95f20a4e'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'Quel est le participe passé de « escribir » ?', 'mcq', '["Escrito","Escribido","Escribado","Escripto"]'::jsonb, 0, 'Comme *abrir → abierto*, *hacer → hecho*, *ver → visto*.', 2),
    ('63468e29-9461-54e4-92af-34c32c67840e'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, '« La puerta está cerrada » comporte un accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *estar*, le participe s’accorde avec le sujet.', 3),
    ('9f201d2f-71ad-5f22-bcdd-69f0f6fa7247'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'Quelle différence entre « fue construida » et « está construida » ?', 'mcq', '["La première décrit l’action, la seconde l’état résultant","Aucune","La première est un futur","La seconde est un passé simple"]'::jsonb, 0, '*Ser* + participe = passive d’action ; *estar* + participe = état.', 4),
    ('cbcab90b-2d8f-5d88-a4eb-17c39e087c5e'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'Quel est le participe passé de « volver » ?', 'mcq', '["Vuelto","Volvido","Volvido/vuelto","Voltado"]'::jsonb, 0, 'Comme *resolver → resuelto*, *poner → puesto*.', 5),
    ('7d9a6906-b365-5268-a5ce-ca4fc3852c71'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'L’espagnol emploie la passive avec « ser » plus souvent que le français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il lui préfère la tournure *se* ou la 3e personne du pluriel.', 6),
    ('3ad5074b-f083-5b5f-ae64-c13e02b8a9ad'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'Quel participe emploie-t-on comme adjectif avec « freír » ?', 'mcq', '["Frito (patatas fritas)","Freído","Freito","Fritado"]'::jsonb, 0, 'Participe double : *he freído* aux temps composés, *frito* comme adjectif.', 7),
    ('7db95207-fce2-57a6-a0fe-ee01037d4a40'::uuid, '622d5d39-36d3-5192-ae0d-a2fde73a6add'::uuid, 'Quel est le participe passé de « satisfacer » ?', 'mcq', '["Satisfecho","Satisfacido","Satisfaído","Satisfacto"]'::jsonb, 0, 'Formé sur *hacer → hecho*.', 8),
    ('79bbeeb7-aa41-593b-8a3d-f80cad8f207c'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, 'Dans « Me gustan las películas », quel est le sujet ?', 'mcq', '["Las películas","Me","Yo","Gustan"]'::jsonb, 0, 'Le verbe s’accorde avec ce qui plaît, pas avec la personne.', 1),
    ('6ba332bc-b0ce-5895-b1c7-cf96d8d0892e'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, 'Comment traduire « j’aime lire et écrire » ?', 'mcq', '["Me gusta leer y escribir","Me gustan leer y escribir","Yo gusto leer y escribir","Me gusto leer y escribir"]'::jsonb, 0, 'Un ou plusieurs infinitifs comptent pour un singulier.', 2),
    ('dcd3d778-eb9c-5d4e-84cd-d63c66b4be60'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, '« A mí me gusta » est une redondance à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : le *a mí* renforce, le pronom *me* reste obligatoire.', 3),
    ('0c6dd739-f4b1-5b47-b8df-e27dffdc6150'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, 'Comment traduire « j’ai mal à la tête » ?', 'mcq', '["Me duele la cabeza","Duelo la cabeza","Tengo dolor la cabeza","Me duelo la cabeza"]'::jsonb, 0, '*Doler* se construit comme *gustar*.', 4),
    ('202f3f44-876b-510b-9dd2-fc3348d91308'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, 'Que répondre à « Me gusta el cine » pour dire « moi aussi » ?', 'mcq', '["A mí también","A mí tampoco","A mí sí","Yo también gusto"]'::jsonb, 0, '*Tampoco* servirait à répondre à une phrase négative.', 5),
    ('8f754c72-6190-5370-a9e8-af8139a908c2'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, '« Me encantan los perros » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Encantar* fonctionne comme *gustar* : accord avec *los perros*.', 6),
    ('c49d88a3-18c7-5a3d-a922-06d8c5762595'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, 'Comment renforcer « le gusta » pour préciser qu’il s’agit de Juan ?', 'mcq', '["A Juan le gusta","Juan le gusta","Le gusta Juan","A Juan gusta"]'::jsonb, 0, 'Le pronom *le* se maintient même quand le nom est exprimé.', 7),
    ('0d431fe7-2fa7-52eb-a3af-e9db55362a3a'::uuid, '2b4b6645-9a21-597b-95e0-9875998b2987'::uuid, 'On peut dire « me gusta muy ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit *me gusta mucho* : *muy* ne modifie jamais un verbe.', 8),
    ('bbb6a88a-20b5-5351-b657-188133c600bb'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, 'Quelle tournure exprime une obligation personnelle ?', 'mcq', '["Tener que + infinitif","Hay que + infinitif","Soler + infinitif","Acabar de + infinitif"]'::jsonb, 0, '*Tengo que estudiar* : l’obligation vise quelqu’un.', 1),
    ('8cd6d1d8-0cb2-5916-a1bc-7f4b5da04bb9'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, '« Hay que » est invariable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’obligation est impersonnelle : aucun sujet, donc aucune variation en personne.', 2),
    ('15c5d628-7769-50e5-8d3f-6319aa9939ee'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, 'Que signifie « Debe de estar enfermo » ?', 'mcq', '["Il doit être malade (supposition)","Il doit rester malade","Il faut qu’il soit malade","Il a dû tomber malade"]'::jsonb, 0, '*Deber de* exprime la probabilité, *deber* seul l’obligation morale.', 3),
    ('382efdb2-7056-5481-8fc9-61b23ec7a270'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, 'Comment traduire « il faut étudier » (en général) ?', 'mcq', '["Hay que estudiar","Tengo que estudiar","Debo estudiar","Es estudiar"]'::jsonb, 0, 'L’obligation impersonnelle passe par *hay que*.', 4),
    ('5b2c6bfb-4dd4-5be5-b160-0a4e6c8248fe'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, 'Après « Es necesario que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Es necesario que vengas* : le jugement impersonnel commande le subjonctif.', 5),
    ('c943aa77-d3a7-5432-8cae-d089ef154a36'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, 'Quelle nuance sépare « tenía que estudiar » et « tuve que estudiar » ?', 'mcq', '["L’imparfait laisse ouvert, le passé simple conclut","Aucune","Le premier est un futur","Le second est impersonnel"]'::jsonb, 0, '*Tuve que* dit que l’obligation a été suivie d’effet.', 6),
    ('6129a105-f80c-5dfe-9430-3cef0495682a'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, '« Haber de + infinitif » appartient à un registre soutenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*He de irme* : obligation atténuée, plus littéraire que *tengo que*.', 7),
    ('c8946da1-aa05-52d8-9651-7336afde6f87'::uuid, '0a705f5b-066f-5cb6-9d40-e0eb8cc59489'::uuid, 'Comment exprimer un ordre direct ?', 'mcq', '["Par l’impératif : ¡Estudia!","Par le gérondif","Par l’infinitif seul","Par le futur"]'::jsonb, 0, 'Et à la forme négative, l’impératif emprunte au subjonctif : *¡No salgas!*', 8),
    ('fbddef5e-6d7a-51ca-b055-6e63304e3a5f'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, 'Que signifie « Suelo levantarme temprano » ?', 'mcq', '["J’ai l’habitude de me lever tôt","Je me lève seul","Je viens de me lever","Je dois me lever tôt"]'::jsonb, 0, '*Soler* + infinitif exprime l’habitude à lui seul.', 1),
    ('e807b6a8-e83c-5329-8640-d75fb91a9117'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, 'À quels temps « soler » s’emploie-t-il ?', 'mcq', '["Au présent et à l’imparfait","À tous les temps","Au passé simple seulement","Au futur seulement"]'::jsonb, 0, 'L’habitude n’est pas un événement daté : ni passé simple, ni futur.', 2),
    ('b6b71799-76c4-5050-b7a6-bd76d1036fba'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, '« Soler » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Suelo, sueles, suele… solemos, soléis, suelen.*', 3),
    ('fc2019ff-b33d-5c6d-b712-ff9873920c04'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, 'Comment traduire « je l’ai rappelé » (une seconde fois) ?', 'mcq', '["Volví a llamarlo","Rellamé","Llamé otra vez lo","Vuelvo llamarlo"]'::jsonb, 0, '*Volver a* + infinitif remplace le préfixe « re- » du français.', 4),
    ('68734a01-506d-5c9c-ae8e-1670fdf23a90'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, '« Acostumbrarse a » signifie « avoir l’habitude de ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La forme pronominale signifie « s’habituer à ».', 5),
    ('7767b53a-595a-5769-a700-03e21d7953d8'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, 'Quel temps exprime seul l’habitude passée ?', 'mcq', '["L’imparfait","Le passé simple","Le futur","Le conditionnel"]'::jsonb, 0, '*Cuando era pequeño, jugaba al fútbol.*', 6),
    ('d84d2c5e-5824-5cdd-b88d-ceba43131f2a'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, '« De vez en cuando » signifie…', 'mcq', '["De temps en temps","Toujours","Jamais","Chaque fois"]'::jsonb, 0, 'Entre *a menudo* (souvent) et *casi nunca* (presque jamais).', 7),
    ('a9e169fe-925c-55a7-90b8-35ecffb73261'::uuid, '9f4fc2ac-0a5d-5f12-8002-4b52b8378b40'::uuid, '« Seguir + gérondif » exprime la continuation d’une action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sigo estudiando español* : je continue d’étudier l’espagnol.', 8),
    ('1a7e42c9-8c12-5a46-adcd-fb68b949b133'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, 'Que signifie « Serán las tres » ?', 'mcq', '["Il doit être trois heures","Il sera trois heures","Il était trois heures","Il faut qu’il soit trois heures"]'::jsonb, 0, 'Le futur de probabilité suppose sur le PRÉSENT.', 1),
    ('0bd30391-5321-5d1a-9a0f-348c8a4687d5'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, 'Le conditionnel de probabilité porte sur…', 'mcq', '["Le passé","Le présent","Le futur","L’avenir proche"]'::jsonb, 0, '*Serían las tres cuando llegó* : il devait être trois heures.', 2),
    ('a5643e2e-7e04-54a0-87c0-f451c4a75653'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, '« Puede que » est suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Puede que llueva* — sans exception.', 3),
    ('8318048f-7f94-56aa-8c49-58c063a4c88e'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, 'Quel mode suit « a lo mejor » ?', 'mcq', '["L’indicatif","Le subjonctif","L’infinitif","Le gérondif"]'::jsonb, 0, 'C’est le piège : à la différence de *quizás*, *a lo mejor* garde l’indicatif.', 4),
    ('74ee74d1-649c-5f30-bd84-138b34cf2cf6'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, '« Debe estudiar » et « Debe de estudiar » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier exprime l’obligation, le second la supposition.', 5),
    ('dce15b0a-c0dc-5069-8c5a-15157e03f3f2'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, '« Quizás venga » plutôt que « quizás viene » signale…', 'mcq', '["Une probabilité plus faible","Une certitude","Un ordre","Un futur proche"]'::jsonb, 0, 'Le subjonctif marque la réserve, l’indicatif l’assurance.', 6),
    ('34e7f01d-5657-55f3-8fd7-d9f1a596282d'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, '« Habrá salido » suppose sur un fait accompli.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur antérieur de probabilité : il a dû sortir.', 7),
    ('9f11070c-afbd-5c3c-95bb-53ee5563b3b2'::uuid, '2241fef7-6f90-5e97-b5d7-0ee9e8891338'::uuid, 'Comment traduire « il devait avoir vingt ans » ?', 'mcq', '["Tendría veinte años","Tendrá veinte años","Tuvo veinte años","Tenía que tener veinte años"]'::jsonb, 0, 'Conditionnel de probabilité, pour supposer sur le passé.', 8),
    ('cf1c3753-2157-59b1-92c1-9c91bc260d3e'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'Comment forme-t-on l’impératif négatif ?', 'mcq', '["Avec le subjonctif présent","Avec l’impératif affirmatif précédé de no","Avec l’infinitif","Avec le futur"]'::jsonb, 0, '*No hables*, *no comas*, *no salgáis*.', 1),
    ('fbd5f458-ae83-55f7-b2ff-de0b31d6e313'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'Quel est l’impératif de « hacer » à la deuxième personne du singulier ?', 'mcq', '["Haz","Hace","Haga","Haced"]'::jsonb, 0, 'Comme *di*, *ve*, *pon*, *sal*, *sé*, *ten*, *ven*.', 2),
    ('d61fa94d-b570-5bb9-a90c-4be9144653b9'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'Après « Te aconsejo que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Te aconsejo que vayas al médico.*', 3),
    ('d7da5a89-b3b9-53f7-8e06-591dd61b4330'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'Comment traduire « tu devrais te reposer » ?', 'mcq', '["Deberías descansar","Debes descansar","Debías descansar","Debe de descansar"]'::jsonb, 0, 'Le conditionnel atténue l’obligation en conseil.', 4),
    ('fc907dce-9534-52ad-9ad8-cb3041ba7ec7'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, '« Ojalá pudiera ayudarte » exprime un souhait réalisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’imparfait du subjonctif marque au contraire l’improbable.', 5),
    ('b8ee6fb1-5dca-5254-adeb-0c9961abd72e'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'Que signifie « Yo que tú, iría al médico » ?', 'mcq', '["À ta place, j’irais chez le médecin","Moi et toi allons chez le médecin","Je te vois chez le médecin","Je dois aller chez le médecin"]'::jsonb, 0, 'La tournure se poursuit au conditionnel.', 6),
    ('86210c53-124e-5e33-83ed-34eed59aebf5'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'L’impératif affirmatif soude les pronoms au verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dímelo* ; au négatif, ils repassent devant : *no me lo digas*.', 7),
    ('e8683354-bfd7-59d2-b5fd-57b239fed3ab'::uuid, 'fe072375-d965-5067-8dfb-1caaf55ee19a'::uuid, 'Quel mode suit « ¿Y si… ? » pour suggérer ?', 'mcq', '["L’indicatif","Le subjonctif","L’impératif","Le conditionnel"]'::jsonb, 0, '*¿Y si salimos esta noche?*', 8),
    ('e03cd84f-1604-5315-8bce-dce7e665270d'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, 'Quelle est la première personne du présent de « hacer » ?', 'mcq', '["Hago","Haco","Hazo","Hacio"]'::jsonb, 0, 'Verbe à *yo* irrégulier : le reste de la conjugaison est régulier.', 1),
    ('2703e234-a191-5734-8ddc-0e65057f39e9'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, 'Quelle est la première personne du présent de « conocer » ?', 'mcq', '["Conozco","Conoco","Conosco","Conogo"]'::jsonb, 0, 'Comme tous les verbes en -cer et -cir : *parezco*, *conduzco*.', 2),
    ('32a6d571-ef48-5b76-8279-c679ecc30031'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, '« Ser », « ir », « haber » et « estar » sont totalement irréguliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Soy*, *voy*, *he*, *estoy* : aucune ne suit un modèle.', 3),
    ('8280a73e-99dc-5c03-b3d4-4b0b7e0ac0f0'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, 'Que signifie « Estudio español desde hace dos años » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié l’espagnol il y a deux ans","J’étudierai deux ans","J’étudiais depuis deux ans"]'::jsonb, 0, 'Le présent couvre l’action commencée dans le passé et qui dure.', 4),
    ('b2829c46-d418-5ce3-a62d-a46c29b419ab'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, '« Tener » cumule un yo irrégulier et une diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Tengo*, puis *tienes, tiene… tenemos, tenéis, tienen*.', 5),
    ('b44c4767-6940-504b-8e71-efd752564983'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, 'Pourquoi « estás » porte-t-il un accent écrit ?', 'mcq', '["L’accent tonique tombe sur la terminaison","C’est un pluriel","Pour le distinguer de « estas »","C’est un subjonctif"]'::jsonb, 0, 'Le second motif est vrai aussi, mais la raison première est prosodique.', 6),
    ('d6737cfa-1ca3-5e16-bf56-c5e68c0ec16a'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, 'Les verbes en -er et en -ir se conjuguent identiquement au présent, sauf…', 'mcq', '["À nosotros et vosotros","À yo et tú","À él et ellos","Nulle part"]'::jsonb, 0, '*Comemos / vivimos*, *coméis / vivís*.', 7),
    ('16da8913-6b2b-5505-b97a-68e963b5bb4d'::uuid, 'fc70df34-acf4-5f11-bc27-c8a92c6c160f'::uuid, 'Le présent peut exprimer un futur proche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mañana salgo a las ocho.*', 8),
    ('12922555-cd7c-5a27-9de7-6e85c9c120f3'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'De quelle forme part-on pour construire le subjonctif présent ?', 'mcq', '["De la première personne du présent de l’indicatif","De l’infinitif","Du participe passé","Du passé simple"]'::jsonb, 0, 'On retire le -o et on inverse la voyelle des terminaisons.', 1),
    ('c22166c1-aa18-55e2-bbae-0e7990bd4630'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'Quelle voyelle prennent les terminaisons du subjonctif des verbes en -ar ?', 'mcq', '["E (hable, hables…)","A","I","O"]'::jsonb, 0, 'Et inversement, les -er et -ir prennent un a : *coma, comas*.', 2),
    ('a4230697-266e-58a7-99b4-fbb7f2c13c12'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'Quel est le subjonctif présent de « tener » à la première personne ?', 'mcq', '["Tenga","Tena","Tienga","Tuviera"]'::jsonb, 0, 'Il hérite du *yo* irrégulier : *tengo → tenga*.', 3),
    ('2fd201f5-1b8f-5cac-9e39-47c222877287'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'Après « Cuando » suivi d’une valeur de futur, on emploie…', 'mcq', '["Le subjonctif","Le futur","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — piège majeur du francophone.', 4),
    ('261124ea-a577-524e-a4bb-c28d36a8a520'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, '« Ser », « ir », « haber », « saber », « dar » et « estar » ont un subjonctif irrégulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sea*, *vaya*, *haya*, *sepa*, *dé*, *esté*.', 5),
    ('9d3b777c-0220-53ca-a152-5bdee69d8e65'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'Au subjonctif, l’affaiblissement touche « nosotros » et « vosotros ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pidamos*, *pidáis* — contrairement à la diphtongue.', 6),
    ('78b35f8c-66e5-5458-9ecf-6d6f37ad98bb'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'Quelle conjonction est toujours suivie du subjonctif ?', 'mcq', '["Para que","Porque","Aunque toujours","Ya que"]'::jsonb, 0, 'Comme *antes de que*, *sin que*, *a menos que*.', 7),
    ('dd274e6e-b5ee-5c63-b396-d84c69a47331'::uuid, '1d523594-f60c-5df6-aea1-d9c2bfb4b6c4'::uuid, 'Quel est le subjonctif présent de « ir » ?', 'mcq', '["Vaya","Vaiga","Iría","Fuera"]'::jsonb, 0, 'L’un des six irréguliers dont la 1re personne ne finit pas par -o.', 8),
    ('122ce2fe-5767-5da4-b5ad-0f76dd97b1e4'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, 'Combien de verbes sont irréguliers à l’imparfait ?', 'mcq', '["Trois : ser, ir, ver","Aucun","Six","Dix"]'::jsonb, 0, '*Era*, *iba*, *veía* — la seule liste courte de la conjugaison espagnole.', 1),
    ('dd35b0f1-3674-5ddc-a089-68526c31c7ad'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, 'Quelle est la terminaison de l’imparfait des verbes en -ar ?', 'mcq', '["-aba","-ía","-ió","-aría"]'::jsonb, 0, 'Les -er et -ir font *-ía*.', 2),
    ('b9227feb-c22e-5faa-a931-429e0c0fd7cf'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, '« Cuando era pequeño, jugaba al fútbol » exprime une habitude.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’emploi principal de l’imparfait avec la description.', 3),
    ('a38763ce-ca5e-5c9c-892e-3b7c908e8193'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, 'Dans « Llovía cuando salí », quel temps fait avancer l’action ?', 'mcq', '["Salí (passé simple)","Llovía (imparfait)","Les deux","Aucun"]'::jsonb, 0, 'L’imparfait pose le décor, le passé simple marque l’événement.', 4),
    ('fec35ee0-9bff-585f-a21e-a431684b5dd8'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, 'Quel est l’imparfait de « ver » ?', 'mcq', '["Veía","Vía","Veaba","Vía/vea"]'::jsonb, 0, 'Il se forme sur l’ancien infinitif *veer*.', 5),
    ('22f9789f-400d-5b05-a127-463e4990b064'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, '« Ayer llovió » et « Ayer llovía » disent exactement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier rapporte un fait, le second décrit un contexte.', 6),
    ('aa3821b6-9f78-5e95-9539-17c14cf6da3b'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, 'Que signifie « Quería pedirle un favor » dans une demande polie ?', 'mcq', '["Je voudrais vous demander un service","Je voulais et je ne veux plus","J’ai demandé un service","Je devrai demander un service"]'::jsonb, 0, 'L’imparfait de politesse atténue la demande.', 7),
    ('7a29d96e-d9bf-5a67-b06d-dc1a9d0442fc'::uuid, '6feb4f84-224f-5278-83fd-f49d0821d059'::uuid, 'L’imparfait peut exprimer une action en cours interrompue par une autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mientras cenábamos, sonó el teléfono.*', 8),
    ('75af7441-2e7d-55e7-9afb-43b4a8b40916'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, 'Comment se forme le pretérito perfecto ?', 'mcq', '["Haber au présent + participe passé","Tener + participe passé","Ser + participe passé","Estar + gérondif"]'::jsonb, 0, '*He comido*, *has estudiado*.', 1),
    ('6743f9cb-d99b-5754-ae67-1e2a389c7a63'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, 'Quel marqueur appelle le pretérito perfecto ?', 'mcq', '["Hoy","Ayer","El año pasado","En 1990"]'::jsonb, 0, 'Comme *esta semana*, *este año*, *ya*, *todavía no*.', 2),
    ('d9464c78-424b-5dab-8754-6ce12216529e'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, 'Le participe passé s’accorde avec le sujet au pretérito perfecto.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec *haber*, jamais d’accord : *ellas han llegado*.', 3),
    ('244b1d9e-ed67-57c2-899c-2a044ca61c01'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, '« Este año he viajado mucho » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période n’est pas achevée : le passé composé s’impose.', 4),
    ('58134453-2cf7-5174-aa4d-b5140774e4f8'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, 'Quelle est la différence entre « Hoy he ido al cine » et « Ayer fui al cine » ?', 'mcq', '["Le premier appartient à une période non achevée","Aucune","Le premier est plus soutenu","Le second est un plus-que-parfait"]'::jsonb, 0, 'Le passé simple coupe du présent, le passé composé raccroche.', 5),
    ('d643554e-92e1-5f29-b120-5d03f0bed47d'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, 'En Amérique latine, le passé simple absorbe souvent le passé composé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hoy comí paella* y est courant, sans être une faute.', 6),
    ('7849f837-90cd-50c6-9eeb-0dd47e394925'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, 'Que peut-on intercaler entre « haber » et le participe ?', 'mcq', '["Rien","Un adverbe","Une négation","Un pronom"]'::jsonb, 0, 'Le bloc est soudé : *No lo he visto nunca*.', 7),
    ('c98ae1f2-9260-5c52-ab7b-c7a813bf71b8'::uuid, '0023cd31-9223-50be-ac82-7b3e3e62dfe4'::uuid, '« Nunca he estado en México » est un bilan de vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période de référence est la vie entière, non achevée.', 8),
    ('e4d958c4-0111-5cad-af3c-930333299d3c'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, 'Quelles terminaisons prend le passé simple des verbes en -ar ?', 'mcq', '["-é, -aste, -ó, -amos, -asteis, -aron","-í, -iste, -ió…","-aba, -abas…","-aré, -arás…"]'::jsonb, 0, '*Hablé, hablaste, habló, hablamos, hablasteis, hablaron.*', 1),
    ('596fa1ed-15a5-5894-ac84-63261949ffbc'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, '« Hablo » et « habló » se distinguent uniquement par l’accent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un est un présent, l’autre un passé simple : l’accent est distinctif.', 2),
    ('d286fe5f-bb89-577f-ac03-1aba83471fe6'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, 'Quel est le passé simple de « tener » à la première personne ?', 'mcq', '["Tuve","Tení","Tuvé","Tenió"]'::jsonb, 0, 'Prétérit fort : radical *tuv-* et terminaisons sans accent.', 3),
    ('0467bb9e-c74c-5f6c-a385-df5b2ab9a613'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, 'Quelle est la troisième personne du pluriel de « decir » au passé simple ?', 'mcq', '["Dijeron","Dijieron","Decieron","Digieron"]'::jsonb, 0, 'Après un radical en -j, le i de la terminaison disparaît.', 4),
    ('e9bcc1eb-3531-5ff6-a738-28cd6eacf7db'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, '« Ser » et « ir » ont la même forme au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Fui, fuiste, fue…* : seul le contexte permet de trancher.', 5),
    ('9873b0d2-6da9-5be3-a7c1-5bf2ff6d2807'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, 'Quel marqueur appelle le passé simple ?', 'mcq', '["Ayer","Hoy","Esta semana","Todavía no"]'::jsonb, 0, 'Comme *anoche*, *el año pasado*, *en 1975*.', 6),
    ('e032a30c-481c-585f-b449-fd7534e65b42'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, 'Quelle est la troisième personne de « dormir » au passé simple ?', 'mcq', '["Durmió","Dormió","Duermió","Durmó"]'::jsonb, 0, 'Les verbes en -ir portent l’affaiblissement aux deux 3es personnes.', 7),
    ('0e0519ad-296c-5277-af22-6b68815e97c0'::uuid, '6bf51bc3-0089-5854-90f8-f6019bfc8156'::uuid, 'Dans un récit, le passé simple fait avancer l’action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’imparfait, lui, décrit le cadre : *Era de noche… De repente, sonó el timbre.*', 8),
    ('fa8546e6-676b-511e-be19-2dbd683a3055'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, 'Sur quoi se construit le futur simple espagnol ?', 'mcq', '["Sur l’infinitif entier","Sur le radical du présent","Sur le participe passé","Sur le passé simple"]'::jsonb, 0, '*Hablaré*, *comeré*, *viviré* : mêmes terminaisons pour les trois groupes.', 1),
    ('e1e43bfe-d931-5f6d-9d00-078c1cc3e6ec'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, 'Quel est le futur de « tener » à la première personne ?', 'mcq', '["Tendré","Teneré","Tenré","Tendría"]'::jsonb, 0, 'Un d remplace la voyelle, comme dans *pondré*, *vendré*, *saldré*.', 2),
    ('f6b481c3-c866-5ff4-bae8-ce0e79ed8158'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, 'Le conditionnel se forme sur le même radical que le futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec les terminaisons de l’imparfait en -ía : *tendría*, *haría*, *diría*.', 3),
    ('17296cdc-4444-5768-9bc8-45fc4ec04786'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, 'Que met-on après « cuando » avec une valeur de futur ?', 'mcq', '["Le subjonctif présent","Le futur simple","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — jamais « cuando llegarás ».', 4),
    ('5246d8f7-68be-5e3c-bef7-b87329cfa61d'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, 'Quel est le futur de « hacer » ?', 'mcq', '["Haré","Haceré","Hará","Hicé"]'::jsonb, 0, 'Radical raccourci, comme *decir → diré*.', 5),
    ('9a76e1c3-c061-5f5f-8148-15773a4f78da'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, '« Serán las tres » exprime une probabilité sur le présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur de supposition : il doit être trois heures.', 6),
    ('f050357b-1b0b-5c95-af96-01925ffceede'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, 'Quelle forme du futur ne porte pas d’accent écrit ?', 'mcq', '["Nosotros (hablaremos)","Yo","Tú","Ellos"]'::jsonb, 0, 'Toutes les autres en portent un : *hablaré, hablarás, hablará, hablaréis, hablarán*.', 7),
    ('f7e7049d-0d8f-5307-a53e-5f7e352b8588'::uuid, 'a6c2a4b0-87f7-5484-9944-8d1c88ec86e5'::uuid, '« Ir a + infinitif » exprime l’intention ou l’imminence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Voy a estudiar* : le futur proche, très employé à l’oral.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('espagnol');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('espagnol')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 297 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 297 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
